<script setup lang="ts">
import {ref} from 'vue'
import {operationJSON,followJob,type OperationJob} from '../api/operations'
import {getMonitorMediaPresets} from '../api/channelMonitor'
const props=defineProps<{ruleId:string;model:string;mode?:string}>()
const emit=defineEmits<{done:[]}>()
const open=ref(false),busy=ref(false),error=ref(''),message=ref(''),mode=ref('text'),adapter=ref(''),presetModel=ref(''),size=ref(''),seconds=ref(4)
const protocols:Record<string,string[]>={image:['openai_image','gemini_image','sub2api_async_image','yunfei_gpt_images','yunfei_gemini_native'],video:['openai_video','newapi_video','ark_native','v6k_video_gateway','yunfei_veo_preview','yunfei_omni'],audio:['sub2api_audio','sub2api_speech','openai_tts','openai_transcription','audio_chat']}
async function show(){
 open.value=true;error.value='';message.value='';mode.value=['image','video','audio'].includes(props.mode||'')?props.mode!:'text';adapter.value='';presetModel.value='';size.value=''
 const name=props.model.toLowerCase()
 if(name.startsWith('gpt-image-')||name==='chatgpt-image-latest'){mode.value='image';adapter.value='openai_image';return}
 if(name.startsWith('gemini-')&&(name.includes('image')||name.includes('nano-banana'))){mode.value='image';adapter.value='gemini_image';return}
 try{const presets=await getMonitorMediaPresets();const exact=presets.find(p=>p.model===props.model);if(exact){mode.value=exact.media_type;adapter.value=exact.adapter;presetModel.value=exact.model;size.value=exact.sizes?.[0]||'';seconds.value=exact.duration?.values?.[0]||4}}catch{}
}
async function run(){busy.value=true;error.value='';message.value='检测中…';try{const job=await followJob(await operationJSON<OperationJob>(`/channel-monitor/rules/${encodeURIComponent(props.ruleId)}/models/check`,{method:'POST',body:JSON.stringify({model:props.model,mode:mode.value,adapter:adapter.value,presetModel:presetModel.value,size:size.value,seconds:seconds.value})}));if(job.failed)throw new Error(job.items.find(i=>i.error)?.error||'检测任务失败');const result=job.items[0]?.result;message.value=result?.status==='healthy'?'实测正常':result?.status==='failed'?'实测失败':result?.status==='config_error'?'访问或配置受限':mode.value==='image'?'图片检测失败':'结果待确认';if(result?.message)message.value+=' · '+result.message;emit('done')}catch(e:any){error.value=e.message;message.value=''}finally{busy.value=false}}
</script>
<template><button type="button" class="shrink-0 rounded border border-blue-500/20 bg-blue-500/10 px-2 py-1 text-xs text-blue-600 dark:text-blue-300" @click.stop="show">实际检测</button><Teleport to="body"><div v-if="open" class="fixed inset-0 z-[170] flex items-center justify-center bg-black/40 p-4" @click.self="!busy&&(open=false)"><section role="dialog" aria-modal="true" aria-label="单次模型实际检测" class="w-full max-w-md space-y-4 rounded-xl border border-border bg-surface p-5 shadow-xl"><div class="flex justify-between"><h3 class="min-w-0 break-words font-semibold">{{model}}</h3><button aria-label="关闭实际检测" :disabled="busy" @click="open=false">✕</button></div><div class="flex flex-wrap gap-2"><select v-model="mode" aria-label="实际检测类型" :disabled="busy" class="rounded border border-border bg-background p-2 text-sm" @change="adapter='';presetModel='' "><option value="text">文本</option><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select><select v-if="mode!=='text'" v-model="adapter" aria-label="实际检测协议" :disabled="busy" class="min-w-0 flex-1 rounded border border-border bg-background p-2 text-sm" @change="presetModel=''"><option value="">精确模型预设</option><option v-for="p in protocols[mode]" :key="p" :value="p">{{p}}</option><option v-if="adapter&&!protocols[mode]?.includes(adapter)" :value="adapter">{{adapter}}</option></select><input v-if="mode==='image'" v-model="size" aria-label="实际检测图片尺寸" placeholder="默认尺寸" :disabled="busy" class="w-full rounded border border-border bg-background p-2 text-sm" /><input v-if="mode==='video'" v-model.number="seconds" aria-label="实际检测视频秒数" type="number" min="1" :disabled="busy" class="w-24 rounded border border-border bg-background p-2 text-sm" /></div><p v-if="message" role="status" class="break-words text-sm text-primary">{{message}}</p><p v-if="error" role="alert" class="break-words text-sm text-red-500">{{error}}</p><button type="button" :disabled="busy" class="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50" @click="run">{{busy?'检测中…':'开始实际检测'}}</button></section></div></Teleport></template>
